import type { FC } from 'react';
import { useEffect, useState } from 'react';
import ToolLayout from '@/components/tools/ToolLayout';
import PillGroup from '@/components/tools/PillGroup';
import { Input } from '@/components/ui/input';
import UploadBox from '@/components/tools/pdf-to-jpg/UploadBox';
import ConversionResult from '@/components/tools/pdf-to-jpg/ConversionResult';
import QualitySlider from '@/components/tools/image-converter/QualitySlider';
import { usePersistentState } from '@/hooks/usePersistentState';
import { useDebouncedValue } from '@/hooks/useDebouncedValue';
import {
  convertPdfToImages,
  buildImagesZip,
  getPdfPageCount,
  parsePageRange,
  type PdfPageImage,
  type ConvertProgress,
} from '@/lib/pdf/convert';

const RESOLUTION_OPTIONS = [
  { value: '1.5', label: 'Standard' },
  { value: '2', label: 'High' },
  { value: '3', label: 'Very High' },
];

const PdfToJpg: FC = () => {
  const [file, setFile] = usePersistentState<File | null>('pdf-to-jpg:file', null);
  const [scale, setScale] = usePersistentState<string>('pdf-to-jpg:scale', '2');
  const [quality, setQuality] = usePersistentState<number>('pdf-to-jpg:quality', 85);
  const [pageRangeInput, setPageRangeInput] = usePersistentState<string>('pdf-to-jpg:pageRange', '');

  const [totalPages, setTotalPages] = useState<number | null>(null);
  const [images, setImages] = useState<PdfPageImage[]>([]);
  const [zipBlob, setZipBlob] = useState<Blob | null>(null);
  const [progress, setProgress] = useState<ConvertProgress | null>(null);
  const [isZipping, setIsZipping] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const debouncedRangeInput = useDebouncedValue(pageRangeInput, 300);

  // Page count is cheap to read (no rendering) — fetch it as soon as a file is
  // picked so the page-range field below can validate against it right away.
  useEffect(() => {
    let ignore = false;

    setTotalPages(null);
    setImages([]);
    setZipBlob(null);
    setProgress(null);
    setError(null);

    if (!file) return;

    getPdfPageCount(file)
      .then((count) => {
        if (!ignore) setTotalPages(count);
      })
      .catch((err: Error) => {
        if (!ignore) setError(err.message || "This file couldn't be read as a PDF");
      });

    return () => {
      ignore = true;
    };
  }, [file]);

  // Generation is explicit (a button), not reactive to every settings tweak —
  // re-rendering every page is expensive, so changing resolution/quality/page
  // range only invalidates the last result (and, cheaply, re-validates the page
  // range as you type) instead of re-converting immediately.
  useEffect(() => {
    setZipBlob(null);
    if (totalPages === null) return;

    const selectedPages = parsePageRange(debouncedRangeInput, totalPages);
    if (debouncedRangeInput.trim() !== '' && selectedPages.length === 0) {
      setError(`No valid pages in that range — this PDF has ${totalPages} page${totalPages === 1 ? '' : 's'}.`);
    } else {
      setError(null);
    }
  }, [scale, quality, debouncedRangeInput, totalPages]);

  const handleGenerate = () => {
    if (!file || totalPages === null) return;

    const selectedPages = parsePageRange(debouncedRangeInput, totalPages);
    if (debouncedRangeInput.trim() !== '' && selectedPages.length === 0) {
      setError(`No valid pages in that range — this PDF has ${totalPages} page${totalPages === 1 ? '' : 's'}.`);
      return;
    }

    setError(null);
    setProgress({ page: 0, total: selectedPages.length });

    convertPdfToImages(file, {
      scale: Number(scale),
      quality,
      pages: selectedPages,
      onProgress: setProgress,
    })
      .then(async (pages) => {
        setImages(pages);
        setProgress(null);
        setIsZipping(true);
        const baseName = file.name.replace(/\.pdf$/i, '') || 'document';
        const zip = await buildImagesZip(pages, baseName);
        setZipBlob(zip);
        setIsZipping(false);
      })
      .catch((err: Error) => {
        setError(err.message || "This file couldn't be converted");
        setImages([]);
        setProgress(null);
        setIsZipping(false);
      });
  };

  const fileBaseName = file ? file.name.replace(/\.pdf$/i, '') || 'document' : 'document';

  return (
    <ToolLayout
      title="PDF to JPG Converter"
      description="Convert every page of a PDF into JPG images and download them as a ZIP — entirely in your browser, nothing is uploaded anywhere."
    >
      <div className="max-w-2xl space-y-6">
        <UploadBox file={file} onSelect={setFile} onClear={() => setFile(null)} />

        {file && (
          <>
            <div>
              <h2 className="text-sm font-medium text-muted-foreground mb-3">
                Pages{totalPages !== null && <span className="text-muted-foreground/60"> ({totalPages} total)</span>}
              </h2>
              <Input
                type="text"
                value={pageRangeInput}
                onChange={(e) => setPageRangeInput(e.target.value)}
                placeholder="All pages, e.g. 1-5, 8, 10-12"
                aria-label="Page range"
              />
            </div>

            <div>
              <h2 className="text-sm font-medium text-muted-foreground mb-3">Resolution</h2>
              <PillGroup aria-label="Resolution" options={RESOLUTION_OPTIONS} value={scale} onChange={setScale} />
            </div>

            <QualitySlider quality={quality} onChange={setQuality} />

            <ConversionResult
              images={images}
              zipBlob={zipBlob}
              fileBaseName={fileBaseName}
              hasFile={!!file}
              progress={progress}
              isZipping={isZipping}
              error={error}
              onGenerate={handleGenerate}
            />
          </>
        )}
      </div>
    </ToolLayout>
  );
};

export default PdfToJpg;
